Section CANSEC2. Context {rc : runConstT}.
Definition rmap_cells (m : amem) : Prop :=
     rw_cells bsegs m 0xb2108 [C8 (Z_to_bv 64 0x149da0)]
  /\ rw_cells bsegs m 0x149da0 [C8 (Z_to_bv 64 4096)]
  /\ rw_cells bsegs m 0xb2118 [C8 (Z_to_bv 64 0x14be28); C8 (Z_to_bv 64 0xb7af8); C8 (Z_to_bv 64 0xba2f8);
